  private rulesArray: Rule[] = [];
  private readonly rstack: Rule[] = [];
  private readonly errors: Error[] = [];
  private readonly recoveryStack: Array<Map<string, Expr>> = [];
  private skipDepth = 0;
  private invertFailures = false;
  private maxFailPos: Savepoint = clonePoint(this.pt);
  private maxFailExpected: string[] = [];
  private expressionCount = 0;
  private readonly maxExpressions: number;
