  private parseRecovery(expr: Expr): Match {
    const recovery = new Map<string, Expr>();
    for (const label of expr.failureLabel ?? []) recovery.set(label, expr.recoverExpr as Expr);
    this.recoveryStack.push(recovery);
    try {
      return this.parseExpr(expr.expr as Expr);
    } finally {
      this.recoveryStack.pop();
    }
  }

  private parseThrow(expr: Expr): Match {
    for (let index = this.recoveryStack.length - 1; index >= 0; index--) {
      const recovery = this.recoveryStack[index].get(expr.label as string);
      if (recovery !== undefined) {
        const result = this.parseExpr(recovery);
        if (result.ok) return result;
      }
    }
    return { value: null, ok: false };
  }
